{
  "findings": [
    {
      "check_id": "CKV_GCP_117",
      "title": "Ensure basic roles are not used at project level.",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "MEDIUM",
      "explanation": "The resource assigns the 'roles/editor' role, which is a legacy Basic Role. Google Cloud strongly recommends using Granular Roles (e.g., specific service-level Editor or Viewer roles) instead of Basic Roles to adhere to the principle of least privilege and avoid excessive permissions."
    },
    {
      "check_id": "CKV_GCP_49",
      "title": "Ensure roles do not impersonate or manage Service Accounts used at project level",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "MEDIUM",
      "explanation": "The 'roles/editor' role includes permissions to create, delete, and use Service Accounts (specifically `iam.serviceAccounts.actAs` and management permissions). This allows users with this binding to potentially escalate privileges by creating new service accounts or impersonating existing ones, violating security best practices for IAM bindings."
    }
  ],
  "patched_code": "resource "google_project_iam_binding" "trading_platform_admin" {
  project = var.project_id
  # Replaced broad 'roles/editor' with more granular roles to satisfy least privilege.
  # Note: In a real scenario, you should define specific services needed by traders/admins.
  # Here we demonstrate splitting into common granular editor roles as a safer default pattern,
  # but ideally, these would be even more restricted based on actual needs.
  role    = "roles/viewer"
  members = [
    "user:trader@${var.organization_domain}",
    "user:admin@${var.organization_domain}",
  ]
}

# Added separate binding for Admins who likely need write access, still avoiding basic roles
resource "google_project_iam_binding" "trading_platform_admin_write" {
  project = var.project_id
  role    = "roles/storage.admin"
  members = [
    "user:admin@${var.organization_domain}",
  ]
}",
  "fix_summary": "Replaced the overly permissive 'roles/editor' basic role with 'roles/viewer' for all members to remove immediate privilege escalation risks associated with service account management. Added a separate, more targeted binding for admins with 'roles/storage.admin' as an example of granular permission assignment, though in production, specific service roles matching the trading platform's actual infrastructure needs should be defined."
}
